    /**
     * Method to retrieve the ThirdParty via an ThirdPartyPrimaryKey.
     * @param 	id Long
     * @return 	ThirdParty
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public ThirdParty handle( FindThirdPartyQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getThirdPartyId() );
    }
    
    /**
     * Method to retrieve a collection of all ThirdPartys
     *
     * @param	query	FindAllThirdPartyQuery 
     * @return 	List<ThirdParty> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<ThirdParty> handle( FindAllThirdPartyQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindThirdParty,
 * but only if the id matches
 *
 * @param		entity	ThirdParty
 */
	protected void emitFindThirdParty( ThirdParty entity ) {
		LOGGER.info("handling emitFindThirdParty" );
		
	    queryUpdateEmitter.emit(FindThirdPartyQuery.class,
	                            query -> query.getFilter().getThirdPartyId().equals(entity.getThirdPartyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllThirdParty
	 * 
	 * @param		entity	ThirdParty
	 */
	protected void emitFindAllThirdParty( ThirdParty entity ) {
		LOGGER.info("handling emitFindAllThirdParty" );
		
	    queryUpdateEmitter.emit(FindAllThirdPartyQuery.class,
	                            query -> true,
	                            entity);
	}

